import { splitFrames } from './split-frames.mjs';

function holdbackLength(pending, delimiter) {
  const max = delimiter.length - 1;
  for (let len = Math.min(max, pending.length); len >= 1; len -= 1) {
    if (pending.slice(pending.length - len) === delimiter.slice(0, len)) {
      return len;
    }
  }
  return 0;
}

function assertWithinMaxBuffer(frames, pending, delimiter, maxBuffer) {
  for (const frame of frames) {
    if (frame.length > maxBuffer) {
      throw new RangeError('frame exceeds maxBuffer');
    }
  }
  const effective = pending.length - holdbackLength(pending, delimiter);
  if (effective > maxBuffer) {
    throw new RangeError('pending payload exceeds maxBuffer');
  }
}

export function createFramer({ delimiter = '\r\n', maxBuffer = 1024 } = {}) {
  if (typeof delimiter !== 'string' || delimiter.length === 0) {
    throw new TypeError('delimiter must be a nonempty string');
  }
  if (!Number.isInteger(maxBuffer) || maxBuffer < 0 || !Number.isFinite(maxBuffer)) {
    throw new RangeError('maxBuffer must be a finite nonnegative integer');
  }

  let pending = '';
  let closed = false;

  return {
    push(chunk) {
      if (closed) {
        throw new Error('framer is closed');
      }
      if (typeof chunk !== 'string') {
        throw new TypeError('chunk must be a string');
      }
      if (chunk.length === 0) {
        return [];
      }
      pending += chunk;
      const { frames, rest } = splitFrames(pending, delimiter);
      assertWithinMaxBuffer(frames, rest, delimiter, maxBuffer);
      pending = rest;
      return frames;
    },
    finish() {
      if (closed) {
        throw new Error('framer is closed');
      }
      if (pending.length > maxBuffer) {
        throw new RangeError('final frame exceeds maxBuffer');
      }
      closed = true;
      const out = pending.length > 0 ? [pending] : [];
      pending = '';
      return out;
    },
  };
}

