export function splitFrames(text, delimiter) {
  if (typeof text !== 'string' || typeof delimiter !== 'string' || delimiter.length === 0) {
    throw new TypeError('text and delimiter must be strings; delimiter must be nonempty');
  }
  const frames = [];
  let i = 0;
  let start = 0;
  while (i <= text.length - delimiter.length) {
    if (text.slice(i, i + delimiter.length) === delimiter) {
      frames.push(text.slice(start, i));
      i += delimiter.length;
      start = i;
    } else {
      i += 1;
    }
  }
  return { frames, rest: text.slice(start) };
}

